import{_ as o,o as s,c as i,ak as n}from"./chunks/framework.C84PSset.js";const a="/projects/ClawPi/en/latest/assets/image1.Bc4wPd86.webp",r="/projects/ClawPi/en/latest/assets/image2.BGjSG9LN.webp",c="/projects/ClawPi/en/latest/assets/image3.C90REELc.webp",h="/projects/ClawPi/en/latest/assets/image4.ChMWhZC0.webp",p="data:image/png;base64,",l="/projects/ClawPi/en/latest/assets/image6.0koqzhXy.webp",t="data:image/png;base64,",d="data:image/png;base64,",g="/projects/ClawPi/en/latest/assets/image10.BBSG0xxB.webp",m="/projects/ClawPi/en/latest/assets/image11.d2zYoyEO.webp",w="data:image/png;base64,",A="data:image/png;base64,",u="/projects/ClawPi/en/latest/assets/image14.CGZBRDfm.webp",b="/projects/ClawPi/en/latest/assets/image15.RJCtsnD8.webp",k="/projects/ClawPi/en/latest/assets/image16.RuDU4nr9.webp",y="/projects/ClawPi/en/latest/assets/image17.T5UkiqPB.webp",f="/projects/ClawPi/en/latest/assets/image18.CJ77kpNy.webp",C="/projects/ClawPi/en/latest/assets/image19.CiAaL2xV.webp",S="/projects/ClawPi/en/latest/assets/image1.C7aY29Bs.webp",v="/projects/ClawPi/en/latest/assets/image2.CToE7LHI.webp",P="/projects/ClawPi/en/latest/assets/image3.S1h1woe5.webp",F="/projects/ClawPi/en/latest/assets/image4.DzCzbt_p.webp",x="/projects/ClawPi/en/latest/assets/image5.DhJSRcP-.webp",E="/projects/ClawPi/en/latest/assets/image6.Bqe0DQSy.webp",W="/projects/ClawPi/en/latest/assets/image7.BpxrT_3h.webp",R="/projects/ClawPi/en/latest/assets/image7.DwQONEYI.webp",T="/projects/ClawPi/en/latest/assets/image9.Dknm49eW.webp",I="data:image/png;base64,",z="/projects/ClawPi/en/latest/assets/image11.79Fzc-JC.webp",D="/projects/ClawPi/en/latest/assets/image4.DxOwkwbQ.webp",V="/projects/ClawPi/en/latest/assets/image13.DVc6qCBT.webp",J="/projects/ClawPi/en/latest/assets/image14.DT_Gx4A0.webp",N="/projects/ClawPi/en/latest/assets/image15.Ba6_t3ma.webp",M="/projects/ClawPi/en/latest/assets/image16.CZfgvaXh.webp",G="/projects/ClawPi/en/latest/assets/image1.B6HgDNr1.webp",L="data:image/png;base64,",O="/projects/ClawPi/en/latest/assets/image3.CB0tA9Z4.webp",U="/projects/ClawPi/en/latest/assets/image4.DxOwkwbQ.webp",q="/projects/ClawPi/en/latest/assets/image5.LwEChT0Y.webp",H="/projects/ClawPi/en/latest/assets/image6.BtveEFGb.webp",j="/projects/ClawPi/en/latest/assets/image7.CP9H00Wn.webp",Y="data:image/png;base64,",K="/projects/ClawPi/en/latest/assets/image2.CXwaN3G5.webp",Q="/projects/ClawPi/en/latest/assets/image3.B71-o44f.webp",B="/projects/ClawPi/en/latest/assets/image4.DxOwkwbQ.webp",X="/projects/ClawPi/en/latest/assets/image5.DDSToXG4.webp",ne=JSON.parse('{"title":"11. Robot Network Configuration Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/11. Robot Network Configuration Course.md","filePath":"docs/11. Robot Network Configuration Course.md"}'),Z={name:"docs/11. Robot Network Configuration Course.md"};function _($,e,ee,te,oe,se){return s(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_11-robot-network-configuration-course" tabindex="-1">11. Robot Network Configuration Course <a class="header-anchor" href="#_11-robot-network-configuration-course" aria-label="Permalink to &quot;11. Robot Network Configuration Course&quot;">​</a></h1><p><a id="p11-1"></a></p><h2 id="_11-1-network-configuration-overview" tabindex="-1">11.1 Network Configuration Overview <a class="header-anchor" href="#_11-1-network-configuration-overview" aria-label="Permalink to &quot;11.1 Network Configuration Overview&quot;">​</a></h2><p>The robot supports the following two network modes:</p><p><strong>AP mode:</strong> The robot creates a Wi-Fi hotspot. A mobile device or computer can connect directly to the hotspot, but normally cannot access the internet through it.</p><p><strong>STA mode:</strong> The robot connects to a specified router Wi-Fi network and can access the internet through that network.</p><p>The robot uses AP mode by default. All robot features remain available in both AP mode and STA mode.</p><p>This course explains several methods for switching between <strong>AP mode</strong> and <strong>STA mode</strong>, as well as how to customize the AP-mode hotspot name.</p><p><a id="p11-2"></a></p><h2 id="_11-2-using-the-wifi-tool-desktop-application" tabindex="-1">11.2 Using the Wifi Tool Desktop Application <a class="header-anchor" href="#_11-2-using-the-wifi-tool-desktop-application" aria-label="Permalink to &quot;11.2 Using the Wifi Tool Desktop Application&quot;">​</a></h2><p><a id="p11-2-1"></a></p><h3 id="_11-2-1-wifi-tool-overview" tabindex="-1">11.2.1 Wifi Tool Overview <a class="header-anchor" href="#_11-2-1-wifi-tool-overview" aria-label="Permalink to &quot;11.2.1 Wifi Tool Overview&quot;">​</a></h3><ul><li>Double-click the Wifi Tool icon <img loading="lazy" height="78" width="77" class="inline-icon" src="'+a+'" style="width:50px;"> on the desktop, then click <strong>Execute</strong> to open the application.</li></ul><img loading="lazy" height="132" width="447" class="common_img" src="'+r+'" style="width:500px;"><ul><li>The Wifi Tool interface appears.</li></ul><img loading="lazy" height="341" width="720" class="common_img" src="'+c+'" style="width:500px;"><p>The following tables describe the interface controls.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Icon</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="36" width="313" class="inline-icon" src="'+h+'" style="width:180px;"><br><img loading="lazy" height="26" width="107" class="inline-icon" src="'+p+'" style="width:90px;"></td><td style="text-align:left;">Current network-mode settings page</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="45" width="142" class="inline-icon" src="'+l+'" style="width:150px;"><br></td><td style="text-align:left;">Interface language. Click to switch languages.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="36" width="175" class="inline-icon" src="'+t+'" style="width:150px;"><br><img loading="lazy" height="37" width="174" class="inline-icon" src="'+d+'" style="width:150px;"></td><td style="text-align:left;">AP mode and STA mode settings. Click to switch pages.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="138" width="695" class="inline-icon" src="'+g+'" style="width:500px;"></td><td style="text-align:left;">Hotspot name, password, and IP address for AP mode</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="172" width="693" class="inline-icon" src="'+m+'" style="width:500px;"></td><td style="text-align:left;">Wi-Fi name, password, and IP address for STA mode</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="58" width="143" class="inline-icon" src="'+w+'" style="width:150px;"></td><td style="text-align:left;">Restarts the robot Wi-Fi service. Click after changing modes to apply the configuration.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="56" width="85" class="inline-icon" src="'+A+'" style="width:100px;"></td><td style="text-align:left;">Exits Wifi Tool</td></tr></tbody></table><p><a id="p11-2-2"></a></p><h3 id="_11-2-2-switching-network-modes" tabindex="-1">11.2.2 Switching Network Modes <a class="header-anchor" href="#_11-2-2-switching-network-modes" aria-label="Permalink to &quot;11.2.2 Switching Network Modes&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Clicking Restart WiFi temporarily disconnects the current VNC, SSH, or mobile connection. This is expected. Wait for the network switch to complete, then reconnect through the new hotspot or IP address.</strong></p></div><ul><li><p><strong>Switching from AP Mode to STA Mode:</strong></p><p>1. Open Wifi Tool and check the current interface language. Then click <strong>LAN Mode</strong> <img loading="lazy" height="36" width="175" class="inline-icon" src="'+t+'" style="width:200px;"> to open the <strong>LAN Mode</strong> settings page.</p></li></ul><img loading="lazy" height="334" width="715" class="common_img" src="'+u+'" style="width:500px;"><img loading="lazy" height="344" width="714" class="common_img" src="'+b+'" style="width:500px;"><p>2. Click <strong>Scan</strong>, select the required Wi-Fi network, then click <strong>Show</strong>.</p><img loading="lazy" height="345" width="723" class="common_img" src="'+k+'" style="width:500px;"><p>3. Enter the password for the selected Wi-Fi network. After confirming the credentials, click <strong>Restart WiFi</strong> and wait for the robot Wi-Fi service to restart.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The Wi-Fi name and password must match. If the robot cannot connect to the router Wi-Fi network, it automatically returns to AP mode.</strong></p></div><img loading="lazy" height="333" width="717" class="common_img" src="'+y+'" style="width:500px;"><img loading="lazy" height="346" width="727" class="common_img" src="'+f+'" style="width:500px;"><p>4. After the Wi-Fi service restarts, the blue <strong>LED2</strong> on the Raspberry Pi expansion board remains on. Check the <strong>IP</strong> field in the upper-right corner of the LCD, for example, <code>192.168.36.174</code>. When an IP address appears, the robot is connected successfully. Enter this address in VNC Viewer to connect to the robot.</p><ul><li><p><strong>Switching from STA Mode to AP Mode:</strong></p><p>1. Open Wifi Tool and check the current interface language.</p><p>2. Make sure that the <strong>Direct Connection Mode</strong> settings page is displayed.</p><p>3. Click <strong>Restart WiFi</strong>, then wait for the robot Wi-Fi service to restart.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Restarting the Wi-Fi service temporarily disconnects the current VNC, SSH, or mobile connection. This is expected. Wait for the robot to recreate its hotspot, then reconnect to the robot hotspot.</strong></p></div></li></ul><img loading="lazy" height="339" width="718" class="common_img" src="'+C+'" style="width:500px;"><p>4. After the Wi-Fi service restarts, the blue <strong>LED2</strong> on the Raspberry Pi expansion board flashes. Check the <strong>SSID</strong> in the upper-right corner of the LCD, for example, <code>HW-5544ea9b</code>. Connect to this hotspot, then use <code>192.168.149.1</code> to connect through VNC Viewer.</p><p><a id="p11-3"></a></p><h2 id="_11-3-switching-from-ap-mode-to-sta-mode" tabindex="-1">11.3 Switching from AP Mode to STA Mode <a class="header-anchor" href="#_11-3-switching-from-ap-mode-to-sta-mode" aria-label="Permalink to &quot;11.3 Switching from AP Mode to STA Mode&quot;">​</a></h2><p><a id="p11-3-1"></a></p><h3 id="_11-3-1-switching-modes-with-the-app" tabindex="-1">11.3.1 Switching Modes with the App <a class="header-anchor" href="#_11-3-1-switching-modes-with-the-app" aria-label="Permalink to &quot;11.3.1 Switching Modes with the App&quot;">​</a></h3><p>1. First, connect the mobile device to a Wi-Fi network. This example uses <code>Hiwonder_5G</code>. On a dual-band router with separate network names, <code>Hiwonder</code> may identify the 2.4 GHz band and <code>Hiwonder_5G</code> the 5 GHz band.</p><img loading="lazy" class="common_img" src="'+S+'" style="width:400px;"><p>2. Open the <strong>WonderPi</strong> app. Select <strong>Starter Kit</strong>, then select <strong>ClawPi</strong>.</p><img loading="lazy" height="576" width="1272" class="common_img" src="'+v+'" style="width:500px;"><p>3. Tap the <strong>+</strong> button in the lower-right corner, then select <strong>LAN Mode</strong>.</p><img loading="lazy" height="575" width="1274" class="common_img" src="'+P+'" style="width:500px;"><p>4. The app prompts for the password of the currently connected Wi-Fi network. Enter the correct password, then tap <strong>OK</strong>.</p><img loading="lazy" height="573" width="1273" class="common_img" src="'+F+'" style="width:500px;"><p>5. Tap <strong>Connect to Device Hotspot</strong>.</p><img loading="lazy" class="common_img" src="'+x+'" style="width:500px;"><p>6. The mobile device opens the Wi-Fi settings page automatically. Select the hotspot whose name begins with <code>HW</code>, enter the password <code>hiwonder</code>, and then return to the app.</p><img loading="lazy" class="common_img" src="'+E+'" style="width:400px;"><p>7. The app starts connecting to the robot.</p><img loading="lazy" class="common_img" src="'+W+'" style="width:500px;"><p>8. After a short wait, the robot icon appears on the main screen, <strong>LED2</strong> on the Raspberry Pi expansion board remains on, and the LCD changes from the Wi-Fi name to an IP address, such as <code>192.168.36.228</code>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If no error appears but the expected result is not shown, press KEY1 on the Raspberry Pi expansion board once, then repeat the procedure from Step 2.</strong></p></div><img loading="lazy" class="common_img" src="'+R+'" style="width:500px;"><p>9. Press and hold the robot icon in the app to view the assigned IP address and device ID.</p><img loading="lazy" class="common_img" src="'+T+'" style="width:500px;"><p>10. Enter this IP address in VNC Viewer to connect to the robot desktop.</p><p>11. To switch from STA mode back to AP mode, briefly press <strong>KEY1</strong> on the Raspberry Pi expansion board. The switch is complete when the blue <strong>LED2</strong> begins flashing and the buzzer beeps once.</p><p><a id="p11-3-2"></a></p><h3 id="_11-3-2-switching-modes-in-the-network-configuration-file" tabindex="-1">11.3.2 Switching Modes in the Network Configuration File <a class="header-anchor" href="#_11-3-2-switching-modes-in-the-network-configuration-file" aria-label="Permalink to &quot;11.3.2 Switching Modes in the Network Configuration File&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Restarting the Wi-Fi service later in this procedure temporarily disconnects the current VNC, SSH, or mobile connection. This is expected. Wait for the robot to connect to the target router Wi-Fi network, then reconnect using its new IP address.</strong></p></div><p>1. Start the robot and connect to it through VNC Viewer.</p><p>2. Click the terminal icon <img loading="lazy" height="32" width="46" class="inline-icon" src="'+I+'" style="width:50px;"> at the top of the desktop to open a terminal.</p><p>3. Enter the following command and press <strong>Enter</strong> to switch to the configuration directory.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hiwonder-toolbox/</span></span></code></pre></div><p>4. Enter the following command and press <strong>Enter</strong> to open the configuration file.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi_conf.py</span></span></code></pre></div><p>5. Press <strong>i</strong> to enter insert mode and set <code>WIFI_MODE</code> to <code>2</code>. A value of <code>1</code> selects AP mode, <code>2</code> selects STA mode, and <code>3</code> selects AP-sharing mode.</p><img loading="lazy" height="226" width="742" class="common_img" src="'+z+'" style="width:500px;"><p>6. Set <code>WIFI_STA_SSID</code> and <code>WIFI_STA_PASSWORD</code> to the router Wi-Fi network name and password. This example uses the Wi-Fi name <code>RobotTest</code> and the password <code>test2026</code>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>A 5 GHz Wi-Fi network provides a higher transmission rate. If the current Wi-Fi connection feels slow, update the configuration to use a 5 GHz Wi-Fi network.</strong></p></div><p>7. After confirming the entries, press <strong>Esc</strong> to exit insert mode. Enter <code>:wq</code>, then press <strong>Enter</strong> to save the file and exit Vim.</p><img loading="lazy" height="84" width="990" class="common_img" src="'+D+'" style="width:500px;"><p>8. Enter the following command to restart the robot Wi-Fi service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi.service</span></span></code></pre></div><p>9. To switch back to AP mode, edit the configuration file again, set <code>WIFI_MODE</code> to <code>1</code>, repeat Steps 7 and 8, and wait for the new configuration to take effect.</p><p><a id="p11-3-3"></a></p><h3 id="_11-3-3-switching-modes-with-wifi-tool" tabindex="-1">11.3.3 Switching Modes with Wifi Tool <a class="header-anchor" href="#_11-3-3-switching-modes-with-wifi-tool" aria-label="Permalink to &quot;11.3.3 Switching Modes with Wifi Tool&quot;">​</a></h3><p>For instructions, see <a href="#p11-2-2">11.2.2 Switching Network Modes / Switching from AP Mode to STA Mode</a>.</p><p><a id="p11-3-4"></a></p><h3 id="_11-3-4-switching-modes-from-the-web-console" tabindex="-1">11.3.4 Switching Modes from the Web Console <a class="header-anchor" href="#_11-3-4-switching-modes-from-the-web-console" aria-label="Permalink to &quot;11.3.4 Switching Modes from the Web Console&quot;">​</a></h3><p>1. Connect the computer to the robot hotspot, for example, <code>HW-6723C5C2</code>.</p><p>2. Open a browser, enter <code>192.168.149.1:8088</code>, and press <strong>Enter</strong>. In the web console, click <strong>Network Settings</strong>.</p><img loading="lazy" class="common_img" src="'+V+'" style="width:500px;"><p>3. Select <strong>LAN Mode</strong>, click the password-display control, and delete the previously saved Wi-Fi name and password. Then click <strong>Scan</strong> to search for nearby networks.</p><img loading="lazy" class="common_img" src="'+J+'" style="width:500px;"><p>4. After the scan is complete, open the <strong>WiFi Name</strong> list, select the required network—<code>Hiwonder</code> in this example—and enter its password.</p><img loading="lazy" height="426" width="1000" class="common_img" src="'+N+'" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Make sure the WiFi name and password match; otherwise, the robot will be unable to connect to the network and will return to AP mode.</strong></p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p></p><p><strong>Delete the saved Wi-Fi name and password before scanning. Otherwise, the list of nearby networks may not appear.</strong></p></div><p>5. Click <strong>Apply and Restart WiFi</strong>, then wait for the mode switch to complete.</p><img loading="lazy" class="common_img" src="'+M+'" style="width:500px;"><p>6. After the switch is complete, the blue <strong>LED2</strong> on the Raspberry Pi expansion board remains on and an <strong>IP</strong> address appears in the upper-right corner of the LCD.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The IP address can be used for remote desktop access. To reopen the robot web console, enter the IP address followed by <code>:8088</code>, for example, <code>192.168.33.228:8088</code>.</strong></p></div><p><a id="p11-4"></a></p><h2 id="_11-4-switching-from-sta-mode-to-ap-mode" tabindex="-1">11.4 Switching from STA Mode to AP Mode <a class="header-anchor" href="#_11-4-switching-from-sta-mode-to-ap-mode" aria-label="Permalink to &quot;11.4 Switching from STA Mode to AP Mode&quot;">​</a></h2><p><a id="p11-4-1"></a></p><h3 id="_11-4-1-switching-modes-with-key1-on-the-raspberry-pi-expansion-board" tabindex="-1">11.4.1 Switching Modes with KEY1 on the Raspberry Pi Expansion Board <a class="header-anchor" href="#_11-4-1-switching-modes-with-key1-on-the-raspberry-pi-expansion-board" aria-label="Permalink to &quot;11.4.1 Switching Modes with KEY1 on the Raspberry Pi Expansion Board&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This example uses <code>Hiwonder</code> as the WiFi network name. Please select the WiFi network name you configured.</strong></p></div><p>1. Press <strong>KEY1</strong> on the Raspberry Pi expansion board to switch the robot from STA mode to AP mode. Wait for the network switch to complete.</p><img loading="lazy" height="261" width="413" class="common_img" src="'+G+'" style="width:500px;"><p>2. After the switch is complete, the blue <strong>LED2</strong> on the Raspberry Pi expansion board flashes and the LCD displays the hotspot name in the upper-right corner, for example, <strong>SSID:</strong> <code>HW-6723C5C2</code>.</p><p><a id="p11-4-2"></a></p><h3 id="_11-4-2-switching-modes-in-the-network-configuration-file" tabindex="-1">11.4.2 Switching Modes in the Network Configuration File <a class="header-anchor" href="#_11-4-2-switching-modes-in-the-network-configuration-file" aria-label="Permalink to &quot;11.4.2 Switching Modes in the Network Configuration File&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Restarting the Wi-Fi service later in this procedure temporarily disconnects the current VNC, SSH, or mobile connection. This is expected. Wait for the robot Wi-Fi service to restart, then reconnect through the robot hotspot using the new IP address.</strong></p></div><p>1. Start the robot and connect to it through VNC Viewer.</p><p>2. Click the terminal icon <img loading="lazy" height="32" width="46" class="inline-icon" src="'+L+'" style="width:50px;"> at the top of the desktop to open a terminal.</p><p>3. Enter the following command and press <strong>Enter</strong> to switch to the configuration directory.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hiwonder-toolbox/</span></span></code></pre></div><p>4. Enter the following command and press <strong>Enter</strong> to open the configuration file.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi_conf.py</span></span></code></pre></div><p>5. Press <strong>i</strong> to enter insert mode and set <code>WIFI_MODE</code> to <code>1</code>. A value of <code>1</code> selects AP mode, <code>2</code> selects STA mode, and <code>3</code> selects AP-sharing mode.</p><img loading="lazy" height="213" width="746" class="common_img" src="'+O+'" style="width:500px;"><p>7. After confirming the entries, press <strong>Esc</strong> to exit insert mode. Enter <code>:wq</code>, then press <strong>Enter</strong> to save the file and exit Vim.</p><img loading="lazy" height="84" width="990" class="common_img" src="'+U+'" style="width:500px;"><p>8. Enter the following command to restart the robot Wi-Fi service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi.service</span></span></code></pre></div><p>9. Wait for the robot Wi-Fi service to restart. When the switch is complete, the blue <strong>LED2</strong> on the Raspberry Pi expansion board flashes and the LCD displays the hotspot name in the upper-right corner, for example, <strong>SSID:</strong> <code>HW-6723C5C2</code>.</p><p><a id="p11-4-3"></a></p><h3 id="_11-4-3-switching-modes-with-wifi-tool" tabindex="-1">11.4.3 Switching Modes with Wifi Tool <a class="header-anchor" href="#_11-4-3-switching-modes-with-wifi-tool" aria-label="Permalink to &quot;11.4.3 Switching Modes with Wifi Tool&quot;">​</a></h3><p>For instructions, see <a href="#p11-2-2">11.2.2 Switching Network Modes / Switching from STA Mode to AP Mode</a>.</p><p><a id="p11-4-4"></a></p><h3 id="_11-4-4-switching-modes-from-the-web-console" tabindex="-1">11.4.4 Switching Modes from the Web Console <a class="header-anchor" href="#_11-4-4-switching-modes-from-the-web-console" aria-label="Permalink to &quot;11.4.4 Switching Modes from the Web Console&quot;">​</a></h3><p>1. Connect the computer to the same router Wi-Fi network as the robot. This example uses the Wi-Fi network <code>Hiwonder</code>.</p><p>2. Check the IP address in the upper-right corner of the robot LCD.</p><img loading="lazy" class="common_img" src="'+q+'" style="width:500px;"><p>3. Open a browser and enter the IP address followed by <code>:8088</code>, for example, <code>192.168.33.228:8088</code>. Press <strong>Enter</strong>, then click <strong>Network Settings</strong> in the web console.</p><img loading="lazy" height="1039" width="1920" class="common_img" src="'+H+'" style="width:500px;"><p>4. Select <strong>Direct Connection Mode</strong>, click the password-display control, and then click <strong>Apply and Restart WiFi</strong>. Wait for the mode switch to complete.</p><img loading="lazy" height="560" width="1049" class="common_img" src="'+j+'" style="width:500px;"><p>5. Wait for the robot Wi-Fi service to restart. When the switch is complete, the blue <strong>LED2</strong> on the Raspberry Pi expansion board flashes and the LCD displays the hotspot name in the upper-right corner, for example, <strong>SSID:</strong> <code>HW-6723C5C2</code>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The IP address can be used for remote desktop access. To reopen the web console in AP mode, enter <code>192.168.149.1:8088</code>.</strong></p></div><p><a id="p11-5"></a></p><h2 id="_11-5-customizing-the-ap-mode-hotspot-name" tabindex="-1">11.5 Customizing the AP-Mode Hotspot Name <a class="header-anchor" href="#_11-5-customizing-the-ap-mode-hotspot-name" aria-label="Permalink to &quot;11.5 Customizing the AP-Mode Hotspot Name&quot;">​</a></h2><p>1. Start the robot and connect to it through VNC Viewer.</p><p>2. Double-click the terminal icon <img loading="lazy" height="32" width="46" class="inline-icon" src="'+Y+'" style="width:60px;"> on the desktop to open a terminal.</p><p>3. Enter the following command and press <strong>Enter</strong> to switch to the configuration directory.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hiwonder-toolbox/</span></span></code></pre></div><p>4. Enter the following command and press <strong>Enter</strong> to open the configuration file.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi_conf.py</span></span></code></pre></div><p>The default configuration uses AP mode. <code>WIFI_MODE = 1</code> selects AP mode. When <code>WIFI_AP_SSID</code> and <code>WIFI_AP_PASSWORD</code> remain commented out, the system uses the default hotspot credentials.</p><img loading="lazy" height="186" width="727" class="common_img" src="'+K+'" style="width:500px;"><p>5. When multiple robots are nearby, assign each device a different hotspot name and password by editing <code>WIFI_AP_SSID</code> and <code>WIFI_AP_PASSWORD</code>. This example uses the hotspot name <code>HW-123</code> and password <code>hiwonder</code>. Press <strong>i</strong> to enter insert mode, remove the <code>#</code> comment markers before <code>WIFI_AP_SSID</code> and <code>WIFI_AP_PASSWORD</code>, and then edit the values.</p><img loading="lazy" height="179" width="735" class="common_img" src="'+Q+'" style="width:500px;"><p>6. After confirming the entries, press <strong>Esc</strong> to exit insert mode. Enter <code>:wq</code>, then press <strong>Enter</strong> to save the file and exit Vim.</p><img loading="lazy" height="84" width="990" class="common_img" src="'+B+'" style="width:500px;"><p>7. Enter the following command in the terminal to restart the robot Wi-Fi service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi.service</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Restarting the Wi-Fi service temporarily disconnects the current VNC, SSH, or mobile connection. This is expected. Wait for the robot to recreate its hotspot, then reconnect through the new hotspot or IP address.</strong></p></div><p>8. Wait for the service to restart, then confirm that the hotspot name has changed.</p><img loading="lazy" height="69" width="355" class="common_img" src="'+X+'" style="width:400px;"><p><a id="p11-6"></a></p><h2 id="_11-6-troubleshooting" tabindex="-1">11.6 Troubleshooting <a class="header-anchor" href="#_11-6-troubleshooting" aria-label="Permalink to &quot;11.6 Troubleshooting&quot;">​</a></h2><p><strong>Q1: Switching Between AP Mode and STA Mode Fails</strong></p><p>Possible causes: The configuration file is incorrect or was not saved, the Wi-Fi service was not restarted, or the router Wi-Fi network name or password is incorrect.</p><p>Solutions:</p><p>1. Check <code>WIFI_MODE</code>, <code>WIFI_AP_SSID</code>, <code>WIFI_AP_PASSWORD</code>, <code>WIFI_STA_SSID</code>, and <code>WIFI_STA_PASSWORD</code>. Make sure that Python strings use the correct quotation marks and that the <code>#</code> comment markers are set correctly.</p><p>2. Enter <code>:wq</code> in Vim and press <strong>Enter</strong> to save the configuration file.</p><p>3. Run the following command to restart the Wi-Fi service:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi.service</span></span></code></pre></div><p>4. Restarting the Wi-Fi service temporarily disconnects the current VNC, SSH, or mobile connection. Wait for the network switch to complete, then reconnect. In AP mode, connect to the robot hotspot and use <code>192.168.149.1</code>. In STA mode, connect through the same router Wi-Fi network and use the robot&#39;s new IP address.</p><p><strong>Q2: Changes to the Configuration File Do Not Take Effect</strong></p><p>Possible causes: The configuration file was not saved, the Wi-Fi service was not restarted, or the previous network connection is still being checked.</p><p>Solutions:</p><p>1. Reopen <code>wifi_conf.py</code> and confirm that the changes were saved. When using Vim, enter <code>:wq</code> to save and exit.</p><p>2. Run <code>sudo systemctl restart wifi.service</code> to apply the configuration.</p><p>3. Wait for the network service to restart, then check the hotspot name or IP address in the upper-right corner of the LCD.</p><p>4. If the change still does not take effect, restart the robot and check the configuration file and network mode again.</p><p><strong>Q3: The Network Connection Disconnects Frequently</strong></p><p>Possible causes: The Wi-Fi signal is weak, the router is unstable, the wireless channel is congested, or the robot is too far from the router.</p><p>Solutions:</p><p>1. Move the robot closer to the router and reduce obstruction from walls or metal objects.</p><p>2. Use 5 GHz Wi-Fi at short range when the signal is strong and both devices support it. Use 2.4 GHz Wi-Fi when greater range or better wall penetration is required.</p><p>3. Change the Wi-Fi channel to reduce interference from nearby networks.</p><p>4. Check that the router is operating correctly.</p><p><strong>Q4: The App Cannot Find the Robot</strong></p><p>Possible causes: The robot hotspot is not active, the mobile device is not connected to the robot hotspot, the app does not have the required permissions, or iOS has not completed the Wi-Fi connection or does not have location services enabled when using LAN mode.</p><p>Solutions:</p><p>1. Confirm that the robot hotspot is active. In AP mode, <strong>LED2</strong> on the Raspberry Pi expansion board normally flashes and the hotspot name appears in the upper-right corner of the LCD.</p><p>2. Connect the mobile device to the robot hotspot whose name begins with <code>HW</code>, then open the app. The default hotspot password is <code>hiwonder</code>.</p><p>3. Make sure that the app has the required network and location permissions. On iOS, wait for the Wi-Fi icon to appear in the status bar before returning to the app.</p><p>4. Tap the refresh icon in the upper-right corner of the app to search for the robot again.</p><p><strong>Q5: The Hotspot Password Has Been Forgotten</strong></p><p>Possible causes: The hotspot password was changed, or the current AP configuration cannot be confirmed.</p><p>Solutions:</p><p>1. The default hotspot password is <code>hiwonder</code>.</p><p>2. If the password was changed, connect to the robot through VNC Viewer and check the current <code>WIFI_AP_PASSWORD</code> value in <code>wifi_conf.py</code> .</p><p>3. If the robot hotspot is unavailable, connect the robot by Ethernet, then use the corresponding IP address to connect through VNC Viewer and check the configuration.</p><p>4. Perform a factory reset only after confirming that no other recovery method is available.</p>',190)])])}const ae=o(Z,[["render",_]]);export{ne as __pageData,ae as default};
